// Real NIST FDS runs started by a tool call. One run at a time; each lands in public/data/fds/runs/<id>/ so the
// app's FDS tab can open it (?view=fds&run=<id>). The case is generated by the same toFds() the shipped runs use.
import { spawn } from 'node:child_process'
import { closeSync, existsSync, mkdirSync, openSync, readFileSync, readdirSync, writeFileSync } from 'node:fs'
import { homedir } from 'node:os'
import { join } from 'node:path'
import { readFdsCsv } from '@/fds/csv'
import { readSmv } from '@/fds/smv'
import { summarize, type FdsSummary } from '@/fds/summary'
import { toFds } from '@/fds/toFds'
import { ToolError, WEB, loadCabin } from './core'

export const RUNS = join(WEB, 'public/data/fds/runs')
const FDS = process.env.FDS ?? join(homedir(), 'FDS/bin/fds_openmp')
const THREADS = process.env.OMP_NUM_THREADS ?? '4'
export const MAX_T_END = 30

export type FdsParams = { g?: number; o2?: number; psia?: number; burner_kw?: number; burner_off_s?: number; t_end?: number; label?: string }

export type RunStatus = {
  id: string
  state: 'running' | 'done' | 'failed'
  label: string
  params: Required<Omit<FdsParams, 'label'>>
  started: string
  /** Simulated seconds reached so far. */
  sim_time_s: number
  wall_clock_s: number
  cells: number
  view: string
  summary?: FdsSummary
  error?: string
}

let active: string | undefined

const dirOf = (id: string) => join(RUNS, id)
const readStatus = (id: string) => JSON.parse(readFileSync(join(dirOf(id), 'status.json'), 'utf8')) as RunStatus
const writeStatus = (s: RunStatus) => writeFileSync(join(dirOf(s.id), 'status.json'), JSON.stringify(s, null, 2))

/** The last "Simulation Time" FDS printed. */
function simTime(id: string): number {
  try {
    const m = [...readFileSync(join(dirOf(id), 'fds.log'), 'utf8').matchAll(/Simulation Time:\s+([\d.]+)/g)].at(-1)
    return m ? Number(m[1]) : 0
  } catch {
    return 0
  }
}

/** Rewrite runs/index.json: the finished runs, in the shape the app's FDS manifest uses. */
function writeIndex() {
  const cases = readdirSync(RUNS, { withFileTypes: true })
    .filter((d) => d.isDirectory() && existsSync(join(RUNS, d.name, 'run.json')))
    .map((d) => JSON.parse(readFileSync(join(RUNS, d.name, 'run.json'), 'utf8')) as { started: string })
    .sort((a, b) => a.started.localeCompare(b.started))
  writeFileSync(join(RUNS, 'index.json'), JSON.stringify({ cases }, null, 2))
}

function finish(id: string, chid: string, code: number | null, t0: number, burstPsia: number, detectors: string[]) {
  const dir = dirOf(id)
  const s = readStatus(id)
  s.wall_clock_s = Math.round((Date.now() - t0) / 1000)
  s.sim_time_s = simTime(id)
  try {
    const out = existsSync(join(dir, `${chid}.out`)) ? readFileSync(join(dir, `${chid}.out`), 'utf8') : ''
    if (code !== 0 || !/STOP: FDS completed successfully/.test(out)) throw new Error(`FDS stopped early (exit ${code}). ${readFileSync(join(dir, 'fds.log'), 'utf8').trim().split('\n').slice(-3).join(' | ')}`)
    const c = JSON.parse(readFileSync(join(dir, 'case.json'), 'utf8'))
    const summary = summarize(readFdsCsv(readFileSync(join(dir, `${chid}_hrr.csv`), 'utf8')), readFdsCsv(readFileSync(join(dir, `${chid}_devc.csv`), 'utf8')), { burnerKw: c.burner.kw, burstPsia, detectors })
    const steps = Number(readFileSync(join(dir, `${chid}_steps.csv`), 'utf8').trim().split('\n').at(-1)!.split(',')[0])
    s.state = 'done'
    s.summary = summary
    writeFileSync(
      join(dir, 'run.json'),
      JSON.stringify({ id, label: s.label, g: c.g, chid, runtime_s: s.wall_clock_s, cells: c.cells, ijk: c.ijk, dx: c.dx, t_end: summary.tEnd, steps, burner: c.burner, surfs: c.surfs, summary, dir: `/data/fds/runs/${id}`, params: s.params, started: s.started, fds: readSmv(readFileSync(join(dir, `${chid}.smv`), 'utf8')).version }, null, 2),
    )
    writeIndex()
  } catch (e) {
    s.state = 'failed'
    s.error = (e as Error).message
  }
  writeStatus(s)
  if (active === id) active = undefined
}

export function runFds(p: FdsParams): RunStatus {
  if (!existsSync(FDS)) throw new ToolError(`FDS is not installed at ${FDS}. Install NIST FDS 6.11 (github.com/firemodels/fds releases) or set the FDS environment variable to the fds binary.`)
  if (active) throw new ToolError(`FDS is busy with run ${active} (one run at a time). Check it with fds_status, then try again.`)
  const { spec, rows, model } = loadCabin()
  const params = {
    g: p.g ?? spec.g,
    o2: p.o2 ?? spec.o2,
    psia: p.psia ?? spec.psi,
    burner_kw: p.burner_kw ?? 75,
    burner_off_s: p.burner_off_s ?? 20,
    t_end: Math.min(MAX_T_END, p.t_end ?? MAX_T_END),
  }
  const stamp = new Date().toISOString().replace(/[-:]/g, '').slice(2, 15).replace('T', '-')
  const id = `run-${stamp}`
  if (existsSync(dirOf(id))) throw new ToolError('A run was started this same second. Try again.')
  const chid = `agent_${stamp.replace('-', '_')}`
  const gText = params.g === 0 ? 'µg' : `${params.g} g`
  const label = p.label?.trim() || `${gText} · ${Math.round(params.o2 * 100)} % O₂ · ${params.burner_kw} kW`
  const c = toFds({ ...spec, g: params.g, o2: params.o2, psi: params.psia }, rows, model, { chid, g: params.g, tEnd: params.t_end, burnerKw: params.burner_kw, burnerOffS: params.burner_off_s })
  const dir = dirOf(id)
  mkdirSync(dir, { recursive: true })
  writeFileSync(join(dir, `${chid}.fds`), c.text)
  const { text: _text, ...meta } = c
  writeFileSync(join(dir, 'case.json'), JSON.stringify({ ...meta, g: params.g }, null, 2))
  const status: RunStatus = { id, state: 'running', label, params, started: new Date().toISOString(), sim_time_s: 0, wall_clock_s: 0, cells: c.cells, view: `?view=fds&run=${id}` }
  writeStatus(status)

  const log = openSync(join(dir, 'fds.log'), 'w')
  const t0 = Date.now()
  const child = spawn(FDS, [`${chid}.fds`], { cwd: dir, stdio: ['ignore', log, log], env: { ...process.env, OMP_NUM_THREADS: THREADS } })
  closeSync(log)
  active = id
  const done = (code: number | null) => finish(id, chid, code, t0, spec.hull.burstPsia, spec.sensors.map((x) => x.id))
  child.on('error', (e) => {
    writeFileSync(join(dir, 'fds.log'), String(e))
    done(-1)
  })
  child.on('exit', done)
  return status
}

/** A run's state. With wait_s, holds the answer until the run ends or the wait is over. */
export async function fdsStatus(p: { id?: string; wait_s?: number }): Promise<RunStatus> {
  const id = p.id ?? active ?? listRuns().at(-1)?.id
  if (!id || !existsSync(join(dirOf(id), 'status.json'))) throw new ToolError(p.id ? `No FDS run "${p.id}".` : 'No FDS run yet. Start one with run_fds.')
  const until = Date.now() + Math.min(120, p.wait_s ?? 0) * 1000
  while (readStatus(id).state === 'running' && Date.now() < until) await new Promise((r) => setTimeout(r, 1000))
  const s = readStatus(id)
  if (s.state === 'running') {
    // A run whose process is gone (the server restarted) will never finish.
    if (active !== id) return { ...s, state: 'failed', error: 'The tools server restarted while this run was going.' }
    s.sim_time_s = simTime(id)
    s.wall_clock_s = Math.round((Date.now() - Date.parse(s.started)) / 1000)
  }
  return s
}

export function listRuns(): RunStatus[] {
  if (!existsSync(RUNS)) return []
  return readdirSync(RUNS, { withFileTypes: true })
    .filter((d) => d.isDirectory() && existsSync(join(RUNS, d.name, 'status.json')))
    .map((d) => readStatus(d.name))
    .sort((a, b) => a.started.localeCompare(b.started))
}
